contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public entry carrying out the property-based test
    // depositAmount: amount to deposit into c
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount, "insufficient test balance");

        // record test contract balance before deposit
        uint balThisBefore = address(this).balance;
        uint balCBefore = address(c).balance;

        // 1) deposit depositAmount into c from this contract
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;

        // read observable state after deposit
        uint balThisAfter = address(this).balance;
        uint balCAfter = address(c).balance;

        // ensure the observable effect of deposit: test contract lost amount and c gained amount
        // (this is a sanity relation used in the final assertion; not an extra require)

        // decide whether withdrawAll will revert or succeed by attempting it
        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint balThisFinal = address(this).balance;
        uint balCFinal = address(c).balance;

        // General rule:
        // - If withdrawAll succeeded then the test contract's Ether balance increased back by exactly depositAmount
        //   (so balThisFinal == balThisAfter + depositAmount) and c's balance decreased by exactly depositAmount
        //   (so balCAfter == balCFinal + depositAmount).
        // - If withdrawAll reverted then both balances remain as-after-deposit.
        assert(
            (!reverted && balThisFinal == balThisAfter + depositAmount && balCAfter == balCFinal + depositAmount)
            || (reverted && balThisFinal == balThisAfter && balCFinal == balCAfter)
        );
    }

    receive() external payable {}
}

